usersRouter.get("/:id", async (req, res) => {
  const userId = req.params.id;
  const seasonId2 = req.query.seasonId || "season-2026-27";
  try {
    const user = await getUserByIdFirestore(userId);
    if (!user) {
      res.status(404).json({ error: "User not found", code: "NOT_FOUND" });
      return;
    }
    const currentClub = await getUserActiveClubFirestore(userId, seasonId2);
    const stats2 = {
      matchesPlayed: 0,
      wins: 0,
      draws: 0,
      losses: 0,
      goalsScored: 0,
      goalsConceded: 0,
      points: 0,
      trophies: 0,
      leaguePosition: 0
    };
    if (currentClub) {
      const confirmedMatches = await getFixturesFirestore({
        clubId: currentClub.id,
        seasonId: seasonId2,
        status: "CONFIRMED"
      });
      for (const m of confirmedMatches) {
        const isHome = m.homeClubId === currentClub.id;
        const isAway = m.awayClubId === currentClub.id;
        if (isHome || isAway) {
          stats2.matchesPlayed++;
          const myScore = isHome ? m.homeScore ?? 0 : m.awayScore ?? 0;
          const oppScore = isHome ? m.awayScore ?? 0 : m.homeScore ?? 0;
          stats2.goalsScored += myScore;
          stats2.goalsConceded += oppScore;
          if (myScore > oppScore) {
            stats2.wins++;
            stats2.points += 3;
          } else if (myScore === oppScore) {
            stats2.draws++;
            stats2.points += 1;
          } else {
            stats2.losses++;
          }
        }
      }
    }
    res.json({
      user: {
        id: user.id,
        username: user.username,
        firstName: user.firstName,
        lastName: user.lastName,
        photoUrl: user.photoUrl,
        isAdmin: user.isAdmin,
        createdAt: user.createdAt
      },
      currentClub,
      stats: stats2
    });
  } catch (err) {
    handleFirestoreError(res, err, `GET /api/users/${userId}`);
  }
});

